import numpy as np
def solve(X,y,theta,alpha):
 X,y,theta=np.asarray(X,float),np.asarray(y,float),np.asarray(theta,float)
 if X.ndim!=2 or y.shape!=(len(X),) or theta.shape!=(X.shape[1],) or alpha<=0: raise ValueError("shape/alpha")
 return theta-alpha*(X.T@(X@theta-y))/len(y)

